// /include/aerial/physics/drone_parameters.hpp
#pragma once

#include <Eigen/Core>

namespace aerial::physics
{
    struct DroneParameters
    {
        // Total drone mass (kg) 
        double mass = 1.0;

        // Principle moments of inertia (kg m^2)
        // X = roll, Y = pitch, Z = yaw
        Eigen::Vector3d inertia = {0.01, 0.01, 0.02};

        // Distance from the centre of mass to each motor (m)
        double arm_length = 0.16;

        // Maximum thrust generated by one motor (N)
        double max_motor_thrust = 5.0;

        // Reaction torque per unit thrust (m)
        double yaw_torque_coefficient = 0.01;

        // Motor thrust response time constant (seconds)
        double motor_time_constant = 0.05;
    };
}
